1	import { partitionKeyFor, topicFor, type DomainEvent } from "../core/events.js";
2	import type { EventPublisher } from "../core/ports.js";
3	
4	/** What would be handed to a Kafka producer: topic, key, serialized value and headers. */
5	export interface ProducedRecord {
6	  readonly topic: string;
7	  readonly key: string;
8	  readonly value: string;
9	  readonly headers: Readonly<Record<string, string>>;
10	}
11	
12	export interface KafkaEventPublisherOptions {
13	  /** Records kept before `publish` starts failing (back-pressure stand-in). */
14	  readonly maxBuffered?: number;
15	}
16	
17	export class BufferOverflowError extends Error {
18	  constructor(limit: number) {
19	    super(`Event buffer is full (${limit} records); drain it before publishing more`);
20	    this.name = "BufferOverflowError";
21	  }
22	}
23	
24	/**
25	 * Simulated Kafka producer: serializes each event and appends it to an in-process buffer
26	 * instead of talking to a broker. The wire format (JSON value, orderId key, topic per event type)
27	 * is the same one the real producer uses.
28	 */
29	export class KafkaEventPublisher implements EventPublisher {
30	  private readonly buffer: ProducedRecord[] = [];
31	  private readonly maxBuffered: number;
32	
33	  constructor(options: KafkaEventPublisherOptions = {}) {
34	    this.maxBuffered = options.maxBuffered ?? 10_000;
35	  }
36	
37	  async publish(event: DomainEvent): Promise<void> {
38	    if (this.buffer.length >= this.maxBuffered) {
39	      throw new BufferOverflowError(this.maxBuffered);
40	    }
41	    this.buffer.push({
42	      topic: topicFor(event),
43	      key: partitionKeyFor(event),
44	      value: JSON.stringify(event),
45	      headers: {
46	        "content-type": "application/json",
47	        "event-type": event.type,
48	        "schema-version": String(event.schemaVersion),
49	      },
50	    });
51	  }
52	
53	  /** Records published so far, oldest first. */
54	  get records(): readonly ProducedRecord[] {
55	    return this.buffer;
56	  }
57	
58	  /** Returns and clears the buffered records. */
59	  drain(): ProducedRecord[] {
60	    return this.buffer.splice(0, this.buffer.length);
61	  }
62	}
